// Code node "Parse Calendly". One item per Calendly email from the "Calendly" Gmail label.
// Host emails look like:
//   Subject: New Event: Dana Lee - 10:00am Tue, Oct 21, 2026 - 30 Minute Meeting
//   Body: Invitee: Dana Lee / Invitee Email: dana@x.org / Event Date/Time: 10:00am - Tuesday, October 21, 2026 (Central Time - US & Canada)
//   Subject: Canceled: Dana Lee - ...
// Anything we can't read still becomes a row with parse = "check", so nothing is lost.
const TZ = 'America/Chicago';
const strip = h => String(h || '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"');

function field(text, label) {
  // "Label: value" on one line, or the label alone with the value on the next line.
  const re = new RegExp('^\\s*' + label + ':?\\s*(.*)$', 'im');
  const m = text.match(re);
  if (!m) return '';
  if (m[1].trim()) return m[1].trim();
  const after = text.slice(m.index + m[0].length).split('\n').map(s => s.trim()).filter(Boolean);
  return after[0] || '';
}

function when(s) {
  // "10:00am - Tuesday, October 21, 2026 (Central ...)" or "10:00am Tue, Oct 21, 2026"
  const m = String(s).match(/(\d{1,2}:\d{2}\s*[ap]m)\s*-?\s*(?:[A-Za-z]+,\s*)?([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})/i);
  if (!m) return '';
  const time = m[1].replace(/\s+/g, '').toLowerCase();
  const mon = m[2].slice(0, 3);
  const d = DateTime.fromFormat(`${time} ${mon} ${m[3]} ${m[4]}`, 'h:mma LLL d yyyy', { zone: TZ, locale: 'en-US' });
  return d.isValid ? d.toISO() : '';
}

return $input.all().map(i => {
  const j = i.json;
  const subject = String(j.subject || '').trim();
  const text = (j.text || j.textPlain || strip(j.textHtml || j.html)).replace(/\r/g, '');
  const canceled = /^\s*(canceled|cancelled)\b/i.test(subject);
  const head = subject.replace(/^[^:]*:\s*/, '').split(' - ');
  const name = field(text, 'Invitee') || head[0] || '';
  const email = (field(text, 'Invitee Email').match(/[^\s<>()]+@[^\s<>()]+\.[a-z]{2,}/i) || [''])[0].toLowerCase();
  const at = when(field(text, 'Event Date/Time')) || when(head[1] || '');
  // Calendly lists custom questions after "Questions:"; keep the first 600 characters.
  const qi = text.search(/^\s*Questions:?\s*$/im);
  const answers = qi >= 0 ? text.slice(qi).replace(/^\s*Questions:?\s*/i, '').split(/\n\s*(View event|Reschedule|Cancel|Pro Tip)/i)[0].replace(/\n{2,}/g, '\n').trim().slice(0, 600) : '';
  return { json: {
    kind: canceled ? 'canceled' : 'booked',
    name: name.replace(/\s+/g, ' ').trim(),
    email,
    consult_at: at,
    answers,
    parse: name && email && at ? 'ok' : 'check',
    subject,
  } };
});

// Code node "Merge booking". Turns each parsed Calendly email into a Leads row (new or updated).
// Matches an existing lead by email, then by name. A booking puts a prep card in the Hub.
const now = DateTime.now().setZone('America/Chicago').toISO();
const leads = $('Read Leads (booking)').all().map(i => i.json).filter(r => r.id);
const COLS = ['id', 'added', 'source', 'name', 'org', 'email', 'handle', 'stage', 'consult_at', 'met_at', 'last_contact', 'step', 'kind', 'card', 'subject', 'body', 'status', 'sent_at', 'notes'];
const low = s => String(s || '').trim().toLowerCase();
const when = s => { const d = DateTime.fromISO(String(s || '')); return d.isValid ? d.setZone('America/Chicago').toFormat("ccc LLL d 'at' h:mma").replace(/AM|PM/, x => x.toLowerCase()) : 'a time I could not read'; };
const out = {};

$('Parse Calendly').all().map(i => i.json).forEach(b => {
  let l = (b.email && leads.find(x => low(x.email) === b.email)) || (b.name && leads.find(x => low(x.name) === low(b.name) && !['won', 'lost'].includes(x.stage)));
  if (!l) {
    l = { id: b.email ? 'em:' + b.email : 'cal:' + Date.now() + Math.random().toString(36).slice(2, 6), added: now, source: 'calendly', name: b.name, org: '', email: b.email,
      handle: '', stage: 'talking', consult_at: '', met_at: '', last_contact: now, step: '', kind: '', card: '', subject: '', body: '', status: '', sent_at: '', notes: '' };
    leads.push(l);
  }
  if (!l.email && b.email) l.email = b.email;
  if (!l.name && b.name) l.name = b.name;
  l.last_contact = now;
  if (b.kind === 'canceled') {
    Object.assign(l, { stage: 'talking', consult_at: '', step: 'canceled_pending', kind: '', card: '', subject: '', body: '', status: '' });
  } else {
    const fix = b.parse === 'ok' ? '' : '\n\nI could not read every detail of this Calendly email ("' + b.subject + '"). Check the name, email and time in the Leads tab.';
    Object.assign(l, {
      stage: 'consult booked', consult_at: b.consult_at || l.consult_at, step: 'booked', kind: 'todo', subject: '', body: '', status: 'drafted',
      card: `${b.name || 'Someone'} booked a consult for ${when(b.consult_at)}.${b.answers ? '\n\nThey wrote:\n' + b.answers : ''}\n\nWant 3 quick fixes ready for the call? In the project, say:\n\nQuick audit for ${l.org || b.name || 'them'}${fix}`,
    });
    if (b.answers && String(l.notes || '').indexOf(b.answers) < 0) l.notes = [l.notes, b.answers].filter(Boolean).join('\n');
  }
  out[l.id] = l;
});

return Object.values(out).map(l => {
  const o = {};
  COLS.forEach(c => { o[c] = l[c] == null ? '' : String(l[c]); });
  o.updated_at = now;
  return { json: o };
});

// Code node "Plan follow-ups". Runs hourly. Reads the Leads and Targets tabs and writes back only rows that changed.
// One open card per lead at a time: while a row is drafted or approved, nothing new is planned for it.
// Copy follows the onboarding playbook (emails C and E) and Graham's rules: short, no em-dashes, links on their own line.
const BOOK = 'https://calendly.com/grahamivy-co/30min';
const CLOSED = ['won', 'lost', 'cold'];
const WAITING = ['drafted', 'approved'];
const now = DateTime.now().setZone('America/Chicago');
const iso = () => now.toISO();
const days = s => { const d = s ? DateTime.fromISO(String(s)) : null; return d && d.isValid ? now.diff(d, 'days').days : 0; };
const hours = s => days(s) * 24;
const first = n => String(n || '').trim().split(/\s+/)[0] || 'there';
const orgOr = (l, alt) => l.org || alt;
const when = s => { const d = DateTime.fromISO(String(s || '')); return d.isValid ? d.setZone('America/Chicago').toFormat("ccc LLL d 'at' h:mma").replace(/AM|PM/, x => x.toLowerCase()) : 'the call'; };

const T = {
  nudge1: l => ({
    subject: 'Quick follow-up',
    email: `Hi ${first(l.name)},\n\nThanks again for reaching out to Open Frame. Happy to answer any questions, or we can talk it through on a free 30-minute call.\n\n${BOOK}\n\nGraham\nOpen Frame`,
    dm: `Hi ${first(l.name)}, thanks again for reaching out. Happy to answer any questions here, or you can grab a free 30-minute call:\n\n${BOOK}`,
  }),
  nudge2: l => ({
    subject: 'Still happy to help',
    email: `Hi ${first(l.name)},\n\nOne last check-in from me. If now isn't the right time, no problem. When it is, pick any open time here:\n\n${BOOK}\n\nGraham`,
    dm: `Hi ${first(l.name)}, one last check-in from me. If now isn't the right time, no problem. When it is, pick any open time here:\n\n${BOOK}`,
  }),
  noshow: l => ({
    subject: 'Sorry we missed each other',
    email: `Hi ${first(l.name)},\n\nLooks like we missed each other. No problem at all. Here's the link to pick a new time:\n\n${BOOK}\n\nGraham`,
    dm: `Hi ${first(l.name)}, looks like we missed each other. No problem at all. Here's the link to pick a new time:\n\n${BOOK}`,
  }),
  canceled: l => ({
    subject: 'Want to pick a new time?',
    email: `Hi ${first(l.name)},\n\nSaw the call was canceled. No problem. If you'd still like to talk, pick any time that works:\n\n${BOOK}\n\nGraham`,
    dm: `Hi ${first(l.name)}, saw the call was canceled. No problem. If you'd still like to talk, pick any time that works:\n\n${BOOK}`,
  }),
  c: l => ({
    subject: 'Any questions on the plan?',
    email: `Hi ${first(l.name)},\n\nChecking in on the plan ${l.org ? 'for ' + l.org : 'we talked about'}. Happy to change anything on it, or walk through it together in 15 minutes.\n\n${BOOK}\n\nGraham`,
    dm: `Hi ${first(l.name)}, checking in on the plan ${l.org ? 'for ' + l.org : 'we talked about'}. Happy to change anything on it, or walk through it together in 15 minutes:\n\n${BOOK}`,
  }),
  e: l => ({
    subject: 'Should I close your file?',
    email: `Hi ${first(l.name)},\n\nI haven't heard back, so I'm guessing the timing isn't right. No problem, I'll close your file for now.\n\nWant our monthly newsletter in the meantime? Reply yes and I'll add you.\n\nIf things change, pick a time here:\n\n${BOOK}\n\nGraham`,
    dm: `Hi ${first(l.name)}, I haven't heard back, so I'm guessing the timing isn't right. No problem, I'll close your file for now. If things change, pick a time here:\n\n${BOOK}`,
  }),
};

// A message card: email when we have an address, otherwise a DM Graham pastes in the Meta inbox.
function message(l, step) {
  const t = T[step](l);
  return l.email
    ? { kind: 'email', subject: t.subject, body: t.email, card: '' }
    : { kind: 'dm', subject: '', body: t.dm, card: '' };
}
const todo = (card) => ({ kind: 'todo', subject: '', body: '', card });
const ask = (kind, card) => ({ kind, subject: '', body: '', card });

// What comes next for one lead, or null. Returns { step, ...card } or { stage } changes.
function next(l) {
  const st = l.stage || 'talking';
  if (st === 'new' || st === 'talking') {
    const since = days(l.last_contact || l.added);
    if (l.step === 'noshow_pending') return { step: 'noshow', ...message(l, 'noshow') };
    if (l.step === 'canceled_pending') return { step: 'canceled', ...message(l, 'canceled') };
    if (!l.step || l.step === 'synced') return since >= 2 ? { step: 'nudge1', ...message(l, 'nudge1') } : null;
    if (['nudge1', 'noshow', 'canceled'].includes(l.step)) return since >= 4 ? { step: 'nudge2', ...message(l, 'nudge2') } : null;
    if (l.step === 'nudge2') return since >= 7 ? { stage: 'cold', step: 'cold', kind: '', card: '', subject: '', body: '', status: '' } : null;
    return null;
  }
  if (st === 'consult booked') {
    if (l.step === 'ask_met') return null; // answered "not yet", wait for the Hub
    const due = l.consult_at ? hours(l.consult_at) >= 1 : days(l.last_contact || l.added) >= 7;
    return due ? { step: 'ask_met', ...ask('ask_met', `Did you meet ${l.name || l.org || 'them'}${l.name && l.org ? ' from ' + l.org : ''}${l.consult_at ? ' on ' + when(l.consult_at) : ''}?`) } : null;
  }
  if (st === 'consult held') {
    const d = days(l.met_at || l.last_contact);
    const org = orgOr(l, l.name || 'them');
    if (!l.step || l.step === 'met') return { step: 'start', ...todo(`Same day as the call. In the project, say:\n\nStart page for ${org}, <plan>, ${[l.name, l.email].filter(Boolean).join(' ')}, <one thing they said>\n\nClaude makes the Start here page and puts Email A in your Gmail drafts.`) };
    if (l.step === 'start') return d >= 2 ? { step: 'fixes', ...todo(`3 quick fixes are due for ${org} (Email B). In the project, say:\n\nQuick fixes email for ${org}`) } : null;
    if (l.step === 'fixes') return d >= 5 ? { step: 'c', ...message(l, 'c') } : null;
    if (l.step === 'c') return d >= 7 ? { step: 'ask_signed', ...ask('ask_signed', `Did ${org} say yes?`) } : null;
    if (l.step === 'ask_signed') return d >= 12 ? { step: 'd', ...todo(`Send ${org} a sample post (Email D). In the project, say:\n\nSample post for ${org}`) } : null;
    if (l.step === 'd') return d >= 30 ? { step: 'e', ...message(l, 'e') } : null;
    if (l.step === 'e') return { stage: 'lost', step: 'closed', kind: '', card: '', subject: '', body: '', status: '' };
  }
  return null;
}

const leads = $('Read Leads').all().map(i => i.json).filter(r => r.id);
const byId = {};
leads.forEach(l => { byId[String(l.id)] = l; });
const changed = {};

// 1. People from outreach and the DM bot who replied, booked or signed (Targets tab) become leads once.
const MAP = { 'replied': 'talking', 'call booked': 'consult booked', 'client': 'won' };
$('Read Targets').all().map(i => i.json).forEach(t => {
  const stage = MAP[String(t.stage || '').trim().toLowerCase()];
  const handle = String(t.handle || '').replace('@', '').trim().toLowerCase();
  if (!stage || !handle || handle.startsWith('template')) return;
  const id = 'ig:' + handle;
  if (byId[id]) return;
  const lead = {
    id, added: iso(), source: t.type === 'prospect' ? 'outreach' : 'dm', name: t.type === 'prospect' ? '' : (t.name || t.handle), org: t.type === 'prospect' ? (t.name || '') : '',
    email: '', handle, stage, consult_at: '', met_at: '', last_contact: t.last_touch || iso(), step: 'synced', kind: '', card: '',
    subject: '', body: '', status: '', sent_at: '', notes: t.notes || t['why them'] || '',
  };
  byId[id] = lead; leads.push(lead); changed[id] = true;
});

// 2. Plan the next card for every open lead that isn't waiting on Graham.
leads.forEach(l => {
  if (CLOSED.includes(l.stage) || WAITING.includes(l.status)) return;
  const n = next(l);
  if (!n) return;
  Object.assign(l, { status: n.kind ? 'drafted' : (n.status ?? l.status) }, n);
  changed[l.id] = true;
});

const COLS = ['id', 'added', 'source', 'name', 'org', 'email', 'handle', 'stage', 'consult_at', 'met_at', 'last_contact', 'step', 'kind', 'card', 'subject', 'body', 'status', 'sent_at', 'notes'];
return leads.filter(l => changed[l.id]).map(l => {
  const o = {};
  COLS.forEach(c => { o[c] = l[c] == null ? '' : String(l[c]); });
  o.updated_at = iso();
  return { json: o };
});

// Code node "Approved emails". Leads rows Graham said yes to in the Hub (kind email, status approved).
return $input.all().map(i => i.json)
  .filter(r => r.id && r.kind === 'email' && r.status === 'approved' && /@/.test(r.email || '') && r.body)
  .map(r => ({ json: { id: r.id, to: r.email, subject: r.subject || 'Following up', text: r.body } }));

// Code node "Mark sent". Runs once per email the SMTP node sent.
const now = DateTime.now().setZone('America/Chicago').toISO();
return $('Approved emails').all().map(i => ({ json: { id: i.json.id, status: 'sent', sent_at: now, last_contact: now, updated_at: now } }));
